void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  float f = float(iFrame) / 30.0;
  vec3 col = vec3(step(uv.x, f) * step(0.85, uv.y));
  col += vec3(step(uv.x, iTimeDelta * 15.0) * step(uv.y, 0.15), 0.0, 0.0);
  col += vec3(0.0, step(uv.x, iFrameRate / 60.0) * step(0.4, uv.y) * step(uv.y, 0.55), 0.0);
  col += vec3(0.0, 0.0, step(uv.x, iSampleRate / 88200.0) * step(0.6, uv.y) * step(uv.y, 0.75));
  fragColor = vec4(col + 0.1, 1.0);
}
